<?php $types = json_decode($request['material_types'], true) ?: []; $video = json_decode((string)$request['video_specs'], true) ?: []; $image = json_decode((string)$request['image_specs'], true) ?: []; $days = $request['deadline'] ? (int)floor((strtotime($request['deadline']) - strtotime(date('Y-m-d'))) / 86400) : null; ?><div class="d-flex justify-content-between align-items-end mb-4"><div><a class="small text-decoration-none" href="/material-requests">All material requests</a><span class="lh-kicker d-block mt-3"><?= $admin ? 'Production brief' : 'Your request' ?></span><h1 class="lh-page-title mb-1"><?= e($request['event_title']) ?></h1><p class="text-secondary mb-0"><?= e($request['location']) ?> · <?= e(date('l, F j, Y', strtotime($request['event_date']))) ?></p></div><span class="badge text-bg-light text-uppercase"><?= e(str_replace('_',' ',$request['status'])) ?></span></div><div class="row g-4"><div class="col-lg-8"><article class="lh-card p-4 p-md-5"><h2 class="h5">Requested deliverables</h2><div class="d-flex flex-wrap gap-2 mb-4"><?php foreach ($types as $type): ?><span class="badge text-bg-primary"><?= e(ucfirst($type)) ?></span><?php endforeach; ?></div><?php if ($video): ?><section class="border-top pt-3 mb-4"><h3 class="h6">Video specifications</h3><p class="small text-secondary mb-1">Formats: <?= e(implode(', ', $video['formats'] ?? [])) ?></p><p class="small text-secondary mb-1">Duration: <?= e($video['duration'] ?? '') ?></p><p class="small text-secondary">Resolution: <?= e($video['resolution'] ?? '') ?></p></section><?php endif; ?><?php if ($image): ?><section class="border-top pt-3 mb-4"><h3 class="h6">Image specifications</h3><p class="small text-secondary mb-1">Formats: <?= e(implode(', ', $image['formats'] ?? [])) ?></p><p class="small text-secondary">Dimensions: <?= e($image['dimensions'] ?? '') ?></p></section><?php endif; ?><section class="border-top pt-3"><h2 class="h6">Event content</h2><p class="text-secondary"><?= nl2br(e($request['event_content'])) ?></p><?php if ($request['additional_instructions']): ?><h3 class="h6 mt-4">Additional instructions</h3><p class="text-secondary mb-0"><?= nl2br(e($request['additional_instructions'])) ?></p><?php endif; ?></section></article></div><div class="col-lg-4"><aside class="lh-card p-4 mb-4"><div class="small text-secondary">Deadline</div><div class="h4 mt-1"><?= $request['deadline'] ? e(date('M j, Y', strtotime($request['deadline']))) : 'Not set' ?></div><?php if ($days !== null): ?><div class="small <?= $days < 0 ? 'text-danger' : 'text-secondary' ?>"><?= $days < 0 ? abs($days).' days overdue' : $days.' days remaining' ?></div><?php endif; ?><?php if ($request['kit_title']): ?><div class="border-top mt-3 pt-3"><div class="small text-secondary">Linked Promotion Kit</div><div class="fw-semibold mt-1"><?= e($request['kit_title']) ?></div></div><?php endif; ?></aside><?php if ($admin): ?><form method="post" action="/material-requests/<?= (int)$request['id'] ?>" class="lh-card p-4 d-grid gap-3"><input type="hidden" name="_token" value="<?= e($_SESSION['csrf']) ?>"><h2 class="h5 mb-0">Update production</h2><select class="form-select" name="status"><option value="requested" <?= $request['status']==='requested'?'selected':'' ?>>Requested</option><option value="in_production" <?= $request['status']==='in_production'?'selected':'' ?>>In production</option><option value="ready" <?= $request['status']==='ready'?'selected':'' ?>>Ready</option><option value="delivered" <?= $request['status']==='delivered'?'selected':'' ?>>Delivered</option><option value="cancelled" <?= $request['status']==='cancelled'?'selected':'' ?>>Cancelled</option></select><input class="form-control" type="date" name="deadline" value="<?= e($request['deadline']) ?>"><select class="form-select" name="promotion_kit_id"><option value="0">No kit linked</option><?php foreach ($kits as $kit): ?><option value="<?= (int)$kit['id'] ?>" <?= (int)$request['promotion_kit_id']===(int)$kit['id']?'selected':'' ?>><?= e($kit['title']) ?></option><?php endforeach; ?></select><textarea class="form-control" name="admin_notes" rows="3" placeholder="Production notes"><?= e($request['admin_notes']) ?></textarea><button class="btn btn-lh-primary" type="submit">Save update</button></form><?php endif; ?></div></div>
